var lab=document.createElement('dialog');lab.className='nw-motion-dialog';lab.setAttribute('aria-labelledby','nw-motion-title');lab.innerHTML='<div class="nw-motion-head"><div><h2 id="nw-motion-title">Motion Lab</h2><small data-motion-mode>Explorar composiciones</small></div><button type="button" class="btn tiny" data-motion-close aria-label="Cerrar Motion Lab">Cerrar</button></div><div class="nw-motion-card nw-motion-workspace"><aside class="nw-motion-library" aria-label="Biblioteca de composiciones"><h3>Biblioteca</h3><div class="nw-motion-category">Profundidad · 2.5D</div><button type="button" class="nw-motion-template" data-motion-template="iso-focus" aria-pressed="true"><svg viewBox="0 0 160 100" aria-hidden="true"><rect x="14" y="31" width="36" height="46" rx="5" fill="#c9b3ff" transform="rotate(-14 32 54)"/><rect x="59" y="20" width="42" height="60" rx="5" fill="#b9f36b"/><rect x="112" y="31" width="36" height="46" rx="5" fill="#ffac83" transform="rotate(14 130 54)"/></svg><span><strong>Foco de láminas</strong><small>Enfoque e inclinación</small></span></button><p class="nw-motion-description">Primera composición disponible. El banco se irá ampliando.</p></aside><section class="nw-motion-stage" aria-label="Vista previa de la composición"><div class="nw-motion-stage-label"><span>FOCO DE LÁMINAS</span><span>Vista previa</span></div><div class="nw-motion-view"><iframe class="nw-motion-frame" title="Vista previa de Foco de láminas" tabindex="-1" sandbox="allow-scripts allow-same-origin"></iframe></div><div class="nw-motion-controls"><button type="button" class="btn tiny" data-motion-play aria-pressed="false">▶ Reproducir</button><input type="range" data-motion-progress aria-label="Momento de la vista previa" min="0" max="100" step="0.1" value="50"><output data-motion-now>50%</output></div></section><aside class="nw-motion-inspector" aria-label="Controles de la composición"><div class="nw-motion-body" data-motion-gallery-details><h3>Foco de láminas</h3><p class="nw-motion-description">Tres láminas se acercan desde un plano inclinado, permanecen de frente y vuelven a alejarse.</p><p class="hint">Imágenes, textos y momentos quedan editables después de insertar.</p><div class="nw-motion-actions"><button type="button" class="btn primary" data-motion-insert-group>Insertar en esta escena</button><button type="button" class="btn tiny" data-motion-insert>Como escena nueva</button></div><p class="nw-motion-description">Elegí dónde colocarla. Después seleccioná el grupo o una imagen y abrí Editar en Motion Lab.</p></div></aside></div>';document.body.appendChild(lab);
