labStyle.textContent+='\n.nw-motion-head-actions{display:flex;gap:6px;align-items:center;flex:none}.nw-motion-head>div:first-child{min-width:0}.nw-motion-head small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nw-motion-dialog.nw-motion-expanded{width:98vw;height:98vh;max-height:98vh}.nw-motion-dialog.nw-motion-expanded .nw-motion-view{justify-content:center}.nw-motion-dialog.nw-motion-expanded .nw-motion-workspace{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr)}.nw-motion-dialog.nw-motion-expanded .nw-motion-library,.nw-motion-dialog.nw-motion-expanded .nw-motion-inspector{display:none!important}\n';
