 labForm.querySelector('[data-motion-background]').closest('.crow').hidden=true;labForm.querySelectorAll(':scope>p.hint').forEach(function(n){n.hidden=true;});labForm.querySelector('[data-motion-composition-settings]').hidden=true;labForm.querySelector('[data-motion-text-style-panel]').after(section);var note=document.createElement('p');note.className='hint';note.dataset.motionStreamSelection='';note.textContent=labIsVortex()?'Cada imagen aparece en todos los anillos. Reemplazarla o ajustar su encuadre actualiza las copias. La selección respeta las esquinas y el orden de los anillos.':labIsCurvedWall()?'Cada imagen se repite sobre la pared. Reemplazarla o ajustar su encuadre actualiza sus copias. La selección sigue la superficie curva visible.':labIsFocusSlider()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su lugar en la secuencia. Duplicar o quitar actúa sobre dos imágenes consecutivas para conservar el ciclo del zigzag.':labIsFocusOrbit()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su lugar en la órbita. La selección sigue su perspectiva y sus esquinas visibles.':labIsSpotlight()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno. El foco elegido se conserva al pasar de casilla al marco completo.':labIsColumnDrift()?'Cada imagen se repite en su columna. Cambiar su contenido o encuadre actualiza sus copias. Duplicar o quitar una fila actúa sobre una imagen de cada columna.':labIsHero()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno. La miniatura y el fondo comparten contenido y enfoque; cada uno adapta el recorte a su proporción.':labIsMosaic()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno. Las aperturas muestran partes de la imagen completa sin deformarla; la selección sigue cada región visible.':labIsStripe()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno. Todas sus franjas comparten la misma imagen y conservan el recorte mientras se deslizan.':labIsWipe()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno. El recorte se conserva durante el barrido; la selección sigue la imagen visible a cada lado del borde.':labIsSplit()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno o panel. Las posiciones 1 y 2 forman el primer par; 3 y 4, el segundo. La selección sigue la parte visible dentro de cada panel.':labIsOrbitShowcase()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su lugar en la órbita. La selección sigue la imagen visible más cercana, incluso cuando la dispersión reúne las imágenes en el centro.':labIsCascadeDeck()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su lugar en la pila. La primera fuente queda delante, también durante los cambios de diagonal.':labIsDance()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su lugar en la coreografía. Las últimas imágenes quedan delante en las superposiciones.':labIsTrail()?'Esta imagen puede aparecer varias veces en la estela. Reemplazarla o ajustar su encuadre actualiza todas sus copias; también podés cambiar su orden.':labIsRing()?'Esta tarjeta recorre el anillo completo. Podés reemplazar la imagen, ajustar su encuadre y cambiar su posición.':labIsCover()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno en el carrusel. La selección respeta la tarjeta visible y sus esquinas en perspectiva.':labIsBottom()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su posición en la rueda. Sus dos copias se actualizan juntas.':labIsSpin()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su posición en la rueda. Su giro y volteo siguen los ajustes de la composición.':labIsWheel()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno en la rueda. Sus copias muestran el mismo contenido.':labIsPhoto()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su posición en la órbita. Las últimas quedan delante en las superposiciones.':labIsBurst()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno en la secuencia.':labIsPeel()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno en la pila. Sus copias muestran siempre el mismo contenido.':labIsBand()?'Esta imagen se repite en la banda. Podés reemplazarla, ajustar su encuadre y cambiar su orden; sus copias se actualizan juntas.':labIsSpiral()?'Esta imagen se repite en la espiral. Podés reemplazarla, ajustar su encuadre y cambiar su orden; sus copias se actualizan juntas.':labIsShift()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su turno en la galería.':labIsDrop()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su posición en la pila. La última queda delante.':labIsZoom()?'Podés reemplazar esta imagen, ajustar su encuadre y cambiar su orden en la secuencia.':labIsDiagonal()?'Esta imagen se repite en la cinta diagonal. Cambiar su contenido o encuadre actualiza todas sus copias; también podés cambiar su orden.':labIsToss()?'Esta imagen ocupa una posición en los lanzamientos. Podés reemplazarla, ajustar su encuadre y cambiar su orden.':labIsFocus()?'Esta imagen se repite en la fila diagonal. Reemplazarla o ajustar su encuadre actualiza sus copias; también podés cambiar su orden.':labIsStack()?'Esta imagen ocupa una posición en la pila. Podés reemplazarla, ajustar su encuadre y cambiar su orden.':labIsCarousel()?'Esta imagen ocupa una posición en el carrusel. Podés reemplazarla, ajustar su encuadre y cambiar su orden.':labIsTickerLoop()?'Esta imagen se repite en filas o columnas. Reemplazarla o ajustar su encuadre actualiza todas sus copias; también podés cambiar su posición.':labIsTicker()?'Esta imagen se repite en las filas. Reemplazarla o ajustar su encuadre actualiza todas sus copias; también podés cambiar su posición.':labIsStage()?'Esta imagen ocupa una posición en la secuencia. Podés reemplazarla, ajustar su encuadre y cambiar su orden.':labIsGrid()?'Esta imagen ocupa una posición en la grilla. Podés reemplazarla y cambiar su orden; los controles de la grilla modifican el movimiento.':'Esta imagen sigue el anillo. Elegila para cambiar su contenido; los controles del anillo modifican el movimiento.';labForm.querySelector('[data-motion-content-panel]').after(note);lab.querySelector('[data-motion-add-image]').textContent='Agregar imagen libre…';lab.querySelector('[data-motion-add-image]').title=labIsTicker()?'Para logos u otras imágenes sobre las filas':labIsSequence()?'Para logos u otras imágenes sobre la secuencia':labIsGrid()?'Para logos u otras imágenes fuera de la grilla':'Para logos u otras imágenes fuera del anillo';labStreamMode();labStreamSelection(labSelectedElement());labUploadState();
